CREATE OR REPLACE FUNCTION public.mod_purchase_sources(p_order_item_ids uuid[])
 RETURNS TABLE(order_item_id uuid, source_car_id uuid)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
